'use strict';
const person='<svg class="icon" viewBox="0 0 20 20" aria-hidden="true"><circle cx="10" cy="5" r="4" fill="currentColor"/><path d="M3 19v-5a7 7 0 0 1 14 0v5z" fill="currentColor"/></svg>';
const car='<svg class="icon" viewBox="0 0 22 20" aria-hidden="true"><rect x="2" y="3" width="18" height="12" rx="2" fill="none" stroke="currentColor" stroke-width="2"/><path d="M6 5v6m5-6v6m5-6v6" stroke="currentColor"/><circle cx="6" cy="17" r="2" fill="currentColor"/><circle cx="16" cy="17" r="2" fill="currentColor"/></svg>';
const names=['카일','레이나','이브','미라','짐칸'], skills=['방어','타격','치유','마력'];
const definitions=[
{id:'normal',label:'기본',title:'기본 · 세 상태 독립',description:'요원 HP, 객차 HP, 충전 상태를 각각 표시합니다.',broken:[],down:[],target:null},
{id:'broken',label:'객차 파손',title:'객차 파손 · 요원 생존',description:'객차 행만 파손 표시. 요원과 스킬 영역은 사용 가능한 표시를 유지합니다. 가동형 지원 중단 목록은 미확정입니다.',broken:[1],down:[],target:null},
{id:'down',label:'요원 다운',title:'요원 다운 · 객차 정상',description:'요원·스킬 영역만 다운 표시. 객차 HP와 상태 상세는 계속 확인합니다.',broken:[],down:[1],target:null},
{id:'both',label:'동시 발생',title:'요원 다운 + 객차 파손',description:'두 상태를 각각 표시합니다. 다운 슬롯을 짐칸으로 바꾸지 않습니다.',broken:[1],down:[1],target:null},
{id:'cargo',label:'짐칸 조준·피격',title:'짐칸 · 실제 객차 표적',description:'예고와 피격 강조는 짐칸 차체와 객차 행에 표시합니다. 가짜 요원 HP·스킬·숨은 공격 기능을 추가하지 않습니다. 보상 소실 표시도 없습니다.',broken:[],down:[],target:{slot:4,kind:'carriage'},cargoHit:true},
{id:'operator',label:'요원 표적',title:'요원 우선 적 · 실제 요원 조준',description:'시안용 적이 요원을 실제 표적으로 선택한 순간입니다. 해당 요원과 요원 HP 행만 예고합니다. 모든 요원에 경고하지 않습니다.',broken:[],down:[],target:{slot:1,kind:'operator'}},
{id:'carriage',label:'객차 표적',title:'객차 우선 적 · 생존 요원이 있어도 객차 조준',description:'동일 생존 상태에서도 시안용 적이 객차를 표적으로 선택합니다. 해당 차체와 객차 HP 행만 예고합니다. 요원에게 숨은 도발·몸막기를 부여하지 않습니다.',broken:[],down:[],target:{slot:1,kind:'carriage'}}
];
class FixtureModel{constructor(){this.state=definitions[0]}select(id){const s=definitions.find(x=>x.id===id);if(!s)throw Error('Invalid fixture state');this.state=s}slots(){return names.map((name,i)=>Object.freeze({name,index:i,cargo:i===4,broken:this.state.broken.includes(i),down:this.state.down.includes(i),operatorHp:i===4?null:(this.state.down.includes(i)?0:[82,72,94,65][i]),carriageHp:this.state.broken.includes(i)?0:(i===4&&this.state.cargoHit?45:[86,78,92,70,84][i]),charge:i===4?null:[100,64,100,82][i],target:this.state.target?.slot===i?this.state.target.kind:null}))}}
class ComparisonView{constructor(){this.cards=document.querySelector('#cards');this.picker=document.querySelector('#state-picker');this.dialog=document.querySelector('#detail');this.abort=null}
bind(actions){this.unbind();this.abort=new AbortController();const opts={signal:this.abort.signal};this.picker.addEventListener('click',e=>{const b=e.target.closest('[data-state]');if(b)actions.select(b.dataset.state)},opts);this.cards.addEventListener('click',e=>{const b=e.target.closest('[data-detail]');if(b)actions.detail(Number(b.dataset.detail));const skill=e.target.closest('[data-skill]');if(skill&&!skill.disabled)actions.skill(Number(skill.dataset.skill))},opts);document.querySelector('#close').addEventListener('click',()=>this.dialog.close(),opts)}
unbind(){this.abort?.abort();this.abort=null;if(this.dialog.open)this.dialog.close()}
render(model){const s=model.state;this.picker.innerHTML=definitions.map(d=>'<button data-state="'+d.id+'" class="'+(s.id===d.id?'active':'')+'" aria-pressed="'+(s.id===d.id)+'">'+d.label+'</button>').join('');document.querySelector('#state-title').textContent=s.title;document.querySelector('#state-summary').textContent=s.description;document.querySelector('#event-note').textContent='';
this.cards.innerHTML=model.slots().map(x=>'<article class="card '+(x.down?'down':'')+'"><div class="portrait" aria-label="표시 도해">'+(x.cargo?'▣':person)+'</div><h3>'+x.name+'</h3>'+(!x.cargo?'<div class="hp '+(x.target==='operator'?'target':'')+'"><span class="hp-label">'+person+'요원'+(x.down?' · 다운':'')+'</span><div class="bar person-bar"><i style="width:'+x.operatorHp+'%"></i></div></div>':'')+'<button class="carriage '+(x.broken?'broken':'')+' '+(x.target==='carriage'?'target':'')+'" data-detail="'+x.index+'" aria-label="'+x.name+' 객차 상태 상세"><span class="hp-label">'+car+'객차</span><div class="bar"><i style="width:'+x.carriageHp+'%"></i></div>'+(x.broken?'<span class="state-word">파손</span>':'')+'</button>'+(!x.cargo?'<div class="charge">'+(x.down?'행동 중단':'충전 '+x.charge+'%')+'<div class="bar"><i style="width:'+x.charge+'%"></i></div></div><button class="skill" data-skill="'+x.index+'" '+(x.down?'disabled':'')+'>'+ (x.down?'다운':skills[x.index])+'</button>':'')+'</article>').join('');
document.querySelector('#roof').innerHTML='<div class="roof-train">'+model.slots().map(x=>'<div class="roof-car '+(x.broken?'broken':'')+' '+(x.target==='carriage'?'target':'')+'"><b>0'+(x.index+1)+'</b><span class="'+(x.target==='operator'?'target-person':'')+'">'+(x.cargo?'짐칸':x.down?'다운':'생존')+'</span>'+ (x.broken?'<span>파손</span>':'')+'</div>').join('')+'</div>';
document.querySelector('#target-note').textContent=s.target?'실제 조준: '+names[s.target.slot]+' '+(s.target.kind==='operator'?'요원':'객차')+(s.cargoHit?' · 피격 강조 예시':''):'도해에는 실제 표적 경고 없음';}
detail(x){document.querySelector('#detail-title').textContent=x.name+' · 객차 상태';document.querySelector('#detail-body').textContent='객차 HP '+x.carriageHp+' / 100 (예시). '+(x.broken?'파손. 가동형 지원 중단 방향 승인, 항목별 목록 미확정. 복구 진행 정보 미연결.':'정상.')+' '+(x.cargo?'요원 HP·스킬 없음. 보상 권리 보존.':'요원 '+(x.down?'다운':'생존')+'. 객차 수리와 요원 복귀는 별개.');this.dialog.showModal()}}
class ComparisonController{constructor(model,view){this.model=model;this.view=view;this.view.bind({select:id=>{model.select(id);view.render(model)},detail:i=>view.detail(model.slots()[i]),skill:i=>{if(!model.slots()[i].down)document.querySelector('#event-note').textContent=names[i]+' 스킬 입력 영역 예시 · 게임 명령 실행 없음'}});view.render(model)}dispose(){this.view.unbind()}}
const controller=new ComparisonController(new FixtureModel(),new ComparisonView());window.addEventListener('pagehide',()=>controller.dispose(),{once:true});
